def figure_tse(ident):
 return f'''<figure id="{ident}" data-origin="human-original"><img src="assets/img/c86/alpha/codex/tse2022-figure1-original.jpg" alt="Planche originale ENKTL, panneaux A à G : atteinte orbitaire et palatine, obstruction laryngée, foyers cutanés et évolution après traitement" loading="lazy" width="1770" height="974"><figcaption><b>Figure originale — ENKTL, du site au retentissement.</b> <b>A–B :</b> les flèches noires montrent l’atteinte orbitaire ; les flèches blanches de B repèrent la nécrose/destruction palatine. <b>C :</b> même patient après début du traitement, observation illustrative. <b>D :</b> autre patient, lumière laryngée très rétrécie sur TDM et fixation en TEP ; le cas publié a nécessité une trachéotomie urgente. <b>E–F :</b> foyers cutanés concordants entre TEP et photographies ; une biopsie nasopharyngée révélait aussi une atteinte malgré l’examen visuel initial. <b>G :</b> évolution de ces lésions après traitement. Les cas ne donnent ni une sensibilité diagnostique ni une garantie de réponse. Original humain de Tse et al., <i>Journal of Hematology &amp; Oncology</i> 2022, figure 1, <a href="https://doi.org/10.1186/s13045-022-01293-5" target="_blank" rel="noopener">source éditeur</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Pixels, lettres et flèches d’origine conservés ; légende explicative française ajoutée.</figcaption></figure>'''
def figure_who(ident):
 return f'''<figure id="{ident}" data-origin="human-original"><img src="assets/img/c86/alpha/codex/who2022-figure7-original.png" alt="Histologie originale OMS des lymphomes TFH : A type angio-immunoblastique, B type folliculaire avec insert PD1, C sans autre spécification" loading="lazy" width="747" height="1430"><figcaption><b>Figure originale — Trois architectures TFH.</b> <b>A :</b> type angio-immunoblastique, architecture effacée et réseau de veinules arborisées ; ce panneau illustre C86.5. <b>B :</b> type folliculaire, amas de cellules pâles au sein de petits lymphocytes ; l’insert montre PD1. <b>C :</b> type sans autre spécification, prolifération en nappes. B et C servent de comparaison et ne doivent pas être tous codés C86.5 du seul fait d’un phénotype TFH. La classification requiert le prélèvement complet, son panel et le contexte. Alaggio et al., <i>Leukemia</i> 2022, figure 7, <a href="https://www.nature.com/articles/s41375-022-01620-2/figures/7" target="_blank" rel="noopener">source éditeur</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Original humain inchangé ; repérage français des panneaux ajouté dans cette légende.</figcaption></figure>'''

def section(marker,title,body,*sources):
 return f'<section class="ilot" id="c86-semio-{marker}" data-semiology="{marker}"><h3>{title}</h3>{body}{refs(*sources)}</section>'
SEMIO='''<h2>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h2><p>Le signe clinique devient utile lorsqu’on explique quel tissu fonctionne normalement, comment il est perturbé et ce que l’observation permet réellement de conclure. Dans C86, le siège et le mode évolutif orientent le prélèvement ; ils ne remplacent jamais la classification tissulaire. Les neuf étapes suivantes relient le raisonnement à des décisions concrètes.</p>'''
SEMIO+=section('normal','1. Normalité : circulation, territoires et contrôles immunitaires',
'''<p>Les lymphocytes se développent dans les organes lymphoïdes primaires puis circulent dans le sang et la lymphe et participent aux réponses dans les organes secondaires. Les ganglions organisent les réponses aux antigènes provenant des tissus ; la rate participe au contrôle des éléments circulant dans le sang. Les muqueuses respiratoires et digestives contiennent aussi du tissu lymphoïde. Il existe donc des cellules immunitaires hors des ganglions : un lymphome n’a pas besoin de produire une masse ganglionnaire palpable.</p><p>Une expansion clonale T peut être normale lorsqu’un antigène sélectionne des cellules portant un récepteur adapté ; la réponse est ensuite régulée. Le signal moléculaire de clonalité n’est donc pas synonyme de cancer. La transformation associe un contexte, une architecture anormale, une cytologie, un phénotype parfois aberrant et des anomalies biologiques. Dans la peau, distinguer surface, derme et hypoderme guide la profondeur nécessaire du prélèvement.</p>''','NORMAL-A','NORMAL-T','ESMO25','MOONLA')
SEMIO+=section('signs','2. Décrire les signes : siège, temps et retentissement',
'''<p>Une <b>papule</b> superficielle qui apparaît puis régresse au sein de poussées répétées n’exprime pas la même dynamique qu’un <b>nodule profond</b> persistant ou qu’une <b>ulcération nécrotique</b> progressive. Pour une LyP présumée, documenter la durée de chaque lésion, les récidives et les lésions qui ne suivent pas le même cours. Pour une panniculite, préciser profondeur, douleur, distribution et symptômes généraux ; l’aspect seul ne sépare pas SPTCL et lupus.</p><p>Une obstruction nasale unilatérale, des épistaxis et une ulcération palatine évoquent un processus local destructeur. Rechercher dyspnée, bruit inspiratoire, modification de voix et difficulté à avaler afin de ne pas manquer le retentissement des voies aériennes. Fièvre avec grosse rate et cytopénies, même sans adénopathie, fait discuter HSTL, infection, toxicité et HLH. Dans l’entéropathie, préciser douleur, diarrhée, perte pondérale, alimentation, saignement et signes d’occlusion.</p>''','TSE','KEMPF','LUPUS','CARVAO','ESsCD26')
SEMIO+=section('mechanisms','3. Expliquer une chaîne plutôt que réciter une association',
table(['Fonction ou structure','Perturbation','Signe et conséquence'],[
['Muqueuse ORL et lumière respiratoire','Infiltration/destruction de l’ENKTL','Ulcération, saignement, obstruction ; un stridor impose de traiter d’abord la menace respiratoire.'],
['Sinusoïdes médullaires, spléniques et hépatiques','Infiltration du HSTL','Hépatosplénomégalie et cytopénies sans masse ganglionnaire dominante ; orienter l’examen médullaire.'],
['Épithélium intestinal et nutrition','Atrophie, lymphocytes aberrants, ulcération ou lymphome','Malabsorption, amaigrissement, hypoalbuminémie ; rechercher RCD-II/EATL et complications.'],
['Régulation de l’activation immunitaire','Hyperinflammation de HLH','Fièvre, cytopénies, atteinte hépatique/coagulation ; soins de soutien et bilan causal en parallèle.'],
['Interactions TFH–cellules B','Microenvironnement tumoral perturbé','Hypergammaglobulinémie et manifestations auto-immunes possibles ; les cellules B EBV positives ne sont pas automatiquement le clone T.']])+
'''<p>Ces chaînes expliquent pourquoi le même symptôme peut avoir plusieurs causes. Une thrombopénie peut résulter d’une infiltration, d’une consommation, d’une séquestration splénique ou d’un traitement. La localiser dans un mécanisme demande la chronologie, l’hémogramme complet, le frottis et les examens ciblés ; le seul code ne tranche pas.</p>''','ESMO25','TSE','ESsCD26','HLH23','OMS22','HUG')
SEMIO+=section('examination','4. Examiner et mesurer dans de bonnes conditions',
'''<p>L’examen comporte l’ensemble de la peau et les aires ganglionnaires, l’abdomen, la cavité buccale et l’évaluation des fonctions vitales selon les signes. Décrire la lésion choisie pour biopsie, sa profondeur et les traitements déjà reçus. Une lésion palatine nécrotique ne doit pas conduire à prélever uniquement du matériel non exploitable. Une lésion sous-cutanée demande une biopsie qui atteint le tissu malade. L’équipe de prélèvement et le laboratoire définissent ensemble les besoins de fixation et de cytométrie.</p><p>Une valeur biologique garde sa méthode et son unité. L’enseignement HUG 2019 donne chez l’adulte une Hb de référence de 140–180 g/L chez l’homme et 120–160 g/L chez la femme, des leucocytes de 4–11 ×10⁹/L et des plaquettes de 150–350 ×10⁹/L. Ce sont des repères datés, pas des normes universelles ni des seuils pédiatriques. La référence du laboratoire du patient prévaut. Une mesure de l’EBV dans le plasma n’est pas interchangeable avec un résultat obtenu sur sang total.</p>''','ESMO25','S2K','HUG','TSE')
SEMIO+=section('interpretation','5. Interpréter : ce que prouve un test et ce qu’il ne prouve pas',
'''<p>Un <b>CD30 positif</b> peut servir à caractériser une prolifération ou à définir une population d’essai. Le seuil ≥75 % de cellules tumorales appartient aux critères du pcALCL dans le contexte adapté ; le seuil ≥10 % était celui d’ECHELON-2. Ni l’un ni l’autre ne dispense d’identifier l’entité. Un panel TFH implique CD4 et au moins deux marqueurs, mais le type angio-immunoblastique nécessite aussi son architecture.</p><p>Un <b>EBER positif</b> localise l’infection dans une population du tissu ; un <b>ADN d’EBV plasmatique</b> est un biomarqueur de charge/réponse. Une <b>fixation TEP</b> n’est pas spécifique de tumeur viable. Une <b>ferritine ≥500 µg/L</b> est un seuil de critères HLH, très peu spécifique chez l’adulte. Une <b>clonalité T</b> peut exister dans une réponse non maligne. L’absence d’adénopathie ne rassure pas devant un tableau de HSTL ; une absence de signe cutané n’exclut pas BPDCN.</p>''','KEMPF','ADCETRIS','OMS22','ESMO25','HLH19','HLH23','BPDCN23')
SEMIO+=section('differentials','6. Faire des comparaisons utiles au lit du patient',
'''<p><b>LyP ou pcALCL :</b> la régression spontanée répétée de chaque lésion oriente la LyP, mais l’histologie et la surveillance d’une lésion atypique restent nécessaires. <b>SPTCL ou panniculite lupique :</b> le siège profond et les nodules se recouvrent ; relier une biopsie représentative au contexte dermatologique et immunologique. <b>ENKTL ou autre ulcération ORL :</b> l’EBV doit être démontré dans les cellules tumorales et la morphologie doit être compatible ; l’aspect nécrotique seul ne suffit pas.</p><p><b>RCD-II ou EATL :</b> des lymphocytes aberrants et une atrophie ne prouvent pas un lymphome invasif ; l’EATL est recherché par l’ensemble du bilan spécialisé. <b>Hémolyse ou infiltration médullaire :</b> la chute d’Hb avec réticulocytose, LDH/bilirubine compatibles et haptoglobine basse oriente une destruction, mais le contexte et le frottis restent essentiels. <b>HLH ou sepsis :</b> ils peuvent coexister ; les distinguer n’autorise pas à retarder le traitement d’une infection possible.</p>''','KEMPF','LUPUS','TSE','ESsCD26','HUG','HLH23')
SEMIO+=section('urgency','7. Reconnaître ce qui ne peut pas attendre',
'''<p>Stridor ou détresse respiratoire dans une atteinte ORL, douleur abdominale aiguë avec suspicion de perforation/occlusion, saignement important et instabilité hémodynamique imposent une prise en charge hospitalière immédiate. Dans un HLH possible avec atteinte d’organes, évaluation, traitement du déclencheur, immunomodulation et soutien se discutent en parallèle ; attendre le résultat génétique ou tous les critères peut être dangereux.</p><p>Sous tagraxofusp, une prise de poids, des œdèmes, une baisse d’albumine ou une hypotension font rechercher une fuite capillaire avant la dose suivante. Sous pégaspargase, douleur abdominale persistante, signes thrombotiques ou ictère demandent une évaluation et une adaptation selon la FI. Sous brentuximab, un nouveau trouble neurologique n’est pas toujours une neuropathie périphérique banale : une suspicion de LEMP entraîne une suspension et un bilan. Le patient doit connaître les signes et le contact de l’équipe.</p>'''+figure_tse('c86-semio-original'),'TSE','ESsCD26','HLH23','ELZONRIS','ONCASPAR','ADCETRIS')
SEMIO+=section('limits','8. Limites : population, technologie et réglementation',
'''<p>Les performances d’un signe isolé ne sont pas chiffrées lorsqu’aucune étude adaptée n’a été lue. Les petits groupes de cas Crohn/HSTL ne décrivent pas tous les HSTL ; les registres cutanés ne donnent pas le pronostic de tout ENKTL nasal. Un odds ratio HAVCR2/HLH n’est ni un risque absolu ni une causalité individuelle démontrée. Les critères HLH pédiatriques servent de cadre chez l’adulte, avec jugement clinique.</p><p>Les doses et indications de la FI suisse concernent un produit précis ; la recommandation européenne et le remboursement suisse répondent à d’autres questions. Les normes HUG adultes ne s’appliquent pas à un nouveau-né ou à la grossesse. Les figures illustrent des patients publiés et une histologie sélectionnée ; elles ne permettent pas un diagnostic personnel par ressemblance. Les sources actuelles peuvent conserver des termes historiques, comme EATL type II : la nomenclature OMS est explicitement distinguée.</p>''','CARVAO','WHO-CUT','MOONLA','HLH19','ESsCD26','OFSP')
SEMIO+=section('sources','9. Relier chaque chaîne aux passages lus',
table(['Question','Passages utilisés'],[
['Territoires normaux et réponse T','OpenStax §21.1 et §21.3, bases descriptives seulement, sans recommandation thérapeutique américaine ni réutilisation de figure.'],['Architecture, phénotype, biopsie','OMS 2022 lymphoïde et dendritique ; ESMO–EHA 2025 diagnostic et stadification.'],['ORL, EBER, plasma et imagerie','Tse 2022 : figure 1, évaluation, mécanismes et traitement ; ESMO–EHA ENKTL.'],['Peau et régression','OMS–EORTC 2018 ; consensus Kempf 2011 ; ESMO cutané 2018 ; S2k 2021/2022.'],['Intestin et hyperinflammation','ESsCD 2025 partie 2 publiée 2026, §§5.3 et 6.2 ; La Rosée 2019 table 2 ; EULAR/ACR 2022 publié 2023.'],['Mesure et sécurité','HUG 2019, tableau hémogramme adulte et hémolyse ; FI suisses exactes Adcetris, Elzonris et Oncaspar.']])+
'''<p>Le dossier de preuves conserve URL, éditeur, version, section réellement consultée, paraphrase, population et limite. Les textes téléchargés mais non parcourus intégralement ne sont pas qualifiés de lectures intégrales. La revue de l’auteur et les tests de navigation ne constituent pas une certification clinique humaine.</p>''','ESMO25','OMS-DC','HLH19','ESsCD26','HUG')

ANAT='''<section class="ilot" id="c86-s-anat-cours"><h2>Anatomie : de la distribution normale au site de prélèvement</h2><p>Les lymphocytes sont présents dans la moelle, le sang, les organes lymphoïdes et les tissus périphériques. La moelle produit les précurseurs ; les lymphocytes T mûrissent dans le thymus puis rejoignent des territoires où ils rencontrent les antigènes. Les ganglions reçoivent la lymphe des tissus, tandis que la rate filtre le sang. Des structures lymphoïdes muqueuses participent à la défense des voies respiratoires et du tube digestif. Cette organisation explique la possibilité d’une maladie extranodale sans adénopathie dominante.</p><p>Dans un ganglion normal, capsule, réseau de soutien, zones lymphocytaires et vaisseaux constituent une architecture utile au diagnostic. Les veinules à endothélium haut facilitent l’entrée de cellules depuis le sang. Une biopsie ne se réduit donc pas à un prélèvement de cellules : elle doit préserver assez d’organisation pour reconnaître une transformation. Le tissu atteint et sa profondeur orientent le geste.</p>'''+table(['Territoire','Lien avec C86','Conséquence pratique'],[
['Cavité nasale, palais, voies aériennes supérieures','ENKTL peut détruire les tissus et s’étendre sous la muqueuse.','Examiner ORL et respiration, cartographier par imagerie, prélever un tissu représentatif.'],['Sinusoïdes de moelle, rate et foie','Distribution typique du HSTL, parfois sans ganglion palpable.','La moelle peut confirmer la maladie ; une TEP seule peut sous-estimer l’infiltration diffuse.'],['Intestin grêle','Atrophie/ulcération dans RCD-II ; EATL et risque de perforation ou d’obstruction.','Biopsies et exploration digestive ciblées ; prise en charge urgente si complication aiguë.'],['Hypoderme','SPTCL autour du tissu adipeux sous-cutané.','Une biopsie limitée à l’épiderme manque le compartiment utile.'],['Peau, moelle et autres sites','BPDCN ou prolifération CD30 selon phénotype et contexte.','Un aspect violacé ou CD56 positif ne suffit pas à définir la lignée.'],['Ganglion','nTFHL-AI et ses diagnostics différentiels.','Privilégier une architecture exploitable, surtout pour distinguer les types TFH.']])+'''<p>Le tableau associe des territoires fréquents ; il ne définit pas des frontières absolues. Une maladie nasale peut disséminer à la peau, et une présentation cutanée peut cacher une atteinte nasopharyngée. Dans la figure, l’examen nasopharyngé initial ne voyait pas de lésion chez le patient E–G, alors que des biopsies étaient positives. L’anatomie guide la recherche sans dispenser d’une exploration complète.</p>'''+figure_tse('c86-anat-original')+'''<div class="key"><b>Normal → pathologique → geste.</b> Connaître le compartiment malade permet de choisir un prélèvement utile ; cela ne permet pas d’identifier la maladie sur le siège seul.</div>'''+refs('NORMAL-A','ESMO25','TSE','OMS22','MOONLA')+'<button class="pareto-btn ui" data-k="pareto-c86-anat">▲ Loi de Pareto — Anatomie</button></section>'

HISTO='''<section class="ilot" id="c86-s-histo-cours"><h2>Histologie : lire ensemble architecture, cellule et marqueur</h2><p>Un tissu lymphoïde normal contient plusieurs populations, des vaisseaux et un réseau de soutien. Une prolifération réactionnelle peut augmenter le nombre de cellules sans constituer une tumeur. À l’inverse, des cellules tumorales ne conservent pas nécessairement tous les marqueurs de la cellule normale : pertes ou diminutions de CD2, CD3, CD5, CD7 ou d’autres antigènes sont possibles. C’est la cohérence de l’ensemble qui fait le diagnostic.</p>'''+table(['Entité','Éléments utiles','Piège'],[
['ENKTL','Morphologie compatible, EBER tumoral, CD56 et/ou molécules cytotoxiques ; profil NK ou T selon les cas.','Un EBER positif dans des cellules B voisines n’identifie pas le clone T/NK.'],['HSTL','Infiltrat intrasinusoïdal, immunophénotype T, contexte hépatosplénique/médullaire.','L’absence de masse ganglionnaire n’exclut pas le diagnostic.'],['SPTCL','Cellules T atypiques entourant les adipocytes, CD8/βF1/cytotoxicité dans le panel adapté.','Lupus et lymphome gamma-delta demandent une confrontation, pas une seule coloration.'],['BPDCN','Panel pDC : CD123, TCF4, TCL1, CD303, CD304, avec profils positifs/négatifs OMS.','CD4/CD56 seuls sont insuffisants ; CD123 est aussi exprimé dans d’autres contextes.'],['nTFHL-AI','Architecture effacée, veinules arborisées, phénotype TFH et contexte intégré.','Deux marqueurs TFH ne définissent pas à eux seuls le type angio-immunoblastique.'],['LyP/pcALCL','CD30 et morphologie, confrontés à la régression ou persistance et au bilan d’extension.','Le seuil d’un essai thérapeutique n’est pas un critère diagnostique interchangeable.']])+'''<p>La figure OMS compare trois architectures qui partagent une différenciation TFH. En A, les veinules arborisées et l’infiltrat contribuent au type angio-immunoblastique. En B, l’architecture folliculaire et l’insert PD1 illustrent un autre type ; C montre une prolifération en nappes. Un petit prélèvement peut manquer les zones discriminantes. L’OMS recommande une désignation prudente sur carotte lorsque l’échantillonnage ne permet pas un sous-typage fiable.</p>'''+figure_who('c86-histo-original')+'''<p>La clonalité est une pièce du raisonnement. Un clone dominant peut être non malin ; une tumeur peut être mal détectée par un test de réarrangement. Le séquençage peut compléter l’analyse, mais une mutation liée à l’hématopoïèse clonale ne localise pas automatiquement la tumeur. L’expert relie les résultats au compartiment et aux cellules effectivement analysés.</p>'''+refs('NORMAL-A','ESMO25','OMS22','OMS-DC','MOONLA','WHO-CUT')+'<button class="pareto-btn ui" data-k="pareto-c86-histo">▲ Loi de Pareto — Histologie</button></section>'

PHYSIO='''<section class="ilot" id="c86-s-physio-cours"><h2>Physiologie : activer, aider, tuer puis réguler</h2><p>Une cellule T reconnaît un antigène présenté dans un contexte de molécules du complexe majeur d’histocompatibilité. Les clones pertinents prolifèrent et se différencient ; des populations mémoire persistent. Les cellules auxiliaires sécrètent des médiateurs qui orientent d’autres cellules, tandis que les cellules cytotoxiques peuvent induire l’apoptose de cibles. Les cellules régulatrices limitent la réponse. Cette expansion contrôlée est physiologique ; elle ne constitue pas en soi une malignité.</p><p>Les fonctions ne se déduisent pas parfaitement d’une seule étiquette : CD4 est associé surtout aux fonctions auxiliaires/régulatrices et CD8 à la cytotoxicité, avec des exceptions. Les cellules NK utilisent également des mécanismes cytotoxiques, dont perforine et granzymes, sans récepteur T réarrangé. C’est pourquoi une protéine cytotoxique ou CD56 ne prouve pas seule une lignée unique. Le BPDCN doit être séparé de ces lignées malgré son ancien nom.</p>'''+table(['Fonction normale','Perturbation liée à la leçon','Retentissement interprétable'],[
['Expansion puis régulation de la réponse','Activation persistante, notamment dans HLH et certains défauts TIM-3','Inflammation systémique et atteinte d’organes ; le traitement du déclencheur et de l’hyperinflammation peut être simultané.'],['Coopération TFH avec les cellules B','Microenvironnement d’un lymphome TFH','Hypergammaglobulinémie, manifestations auto-immunes ou proliférations B associées possibles.'],['Défense des tissus périphériques','Prolifération extranodale T/NK','Atteintes de peau, muqueuse, intestin ou organes sans obligation d’adénopathie dominante.'],['Renouvellement sanguin et filtration splénique','Infiltration, inflammation, séquestration ou toxicité','Cytopénies de mécanismes différents à distinguer par la chronologie et le bilan.']])+'''<p>Dans nTFHL-AI, la perturbation ne concerne pas seulement le clone T. Les cellules et médiateurs voisins peuvent être responsables d’une grande partie des signes. Une augmentation polyclonale des immunoglobulines ne signifie pas un myélome ; des cellules B EBER positives ne rendent pas le lymphome T lui-même EBV positif. Une hémolyse auto-immune demande des signes biologiques de destruction et pas seulement un test direct à l’antiglobuline positif.</p>'''+figure_who('c86-physio-original')+'''<p>Dans le HLH, la fonction effectrice échappe à sa régulation et s’accompagne de lésions d’organes. Le syndrome peut être génétique, infectieux, malin ou associé à une maladie inflammatoire ; plusieurs contributeurs peuvent coexister. La présence d’hémophagocytose n’est qu’un indice. Le clinicien suit l’évolution des fonctions vitales et des biomarqueurs pour apprécier la dynamique, plutôt que d’attendre un signe histologique unique.</p>'''+refs('NORMAL-T','ESMO25','OMS22','HLH19','HLH23','MOONLA','HUG')+'<button class="pareto-btn ui" data-k="pareto-c86-physio">▲ Loi de Pareto — Physiologie</button></section>'

BIO='''<section class="ilot" id="c86-s-bio-cours"><h2>Biochimie : dépendance métabolique, signal viral et biomarqueur</h2><p>Une cellule doit fournir les acides aminés nécessaires à sa synthèse protéique. Une faible capacité de synthèse de l’asparagine rend certaines cellules d’ENKTL dépendantes de l’apport extracellulaire. L’asparaginase diminue cet apport ; la pégylation modifie l’exposition et l’immunogénicité de l’enzyme. Une activité administrée, une activité mesurée et une efficacité tumorale sont trois niveaux différents : des anticorps peuvent inactiver l’enzyme malgré l’administration du produit.</p><figure id="c86-bio-causal"><div class="two"><div class="card"><h4>Chaîne métabolique</h4><p>Faible activité d’asparagine synthétase → compensation limitée de la déplétion extracellulaire → vulnérabilité à l’asparaginase.</p></div><div class="card"><h4>Chaîne de résistance</h4><p>Expression de P-gp et phénotype de multirésistance → mauvais résultats des programmes à anthracycline → choix de schémas sans anthracycline dans l’ENKTL.</p></div></div><figcaption>Diagramme causal pédagogique, sans structure anatomique ; relations décrites dans Tse 2022 et ESMO–EHA 2025. Les flèches expliquent une stratégie, pas une réponse individuelle garantie.</figcaption></figure><p>Les conséquences métaboliques ne sont pas exclusivement tumorales. La FI Oncaspar décrit une altération de la synthèse de protéines circulantes, avec hypoalbuminémie et anomalies de coagulation possibles. Pancréatite, intolérance au glucose et atteinte hépatique expliquent la surveillance clinique et biologique. Une baisse de fibrinogène peut donc provenir du traitement aussi bien que d’un syndrome inflammatoire ; la chronologie aide à distinguer les mécanismes.</p><p>L’ADN d’EBV plasmatique illustre un autre lien biochimie–clinique. La mort de cellules infectées libère des fragments détectables. Dans l’ENKTL, le signal suit la charge et la réponse ; le sang total inclut aussi les cellules B mémoires infectées et peut donner un signal d’une autre origine. Une limite de détection est une propriété analytique, pas une frontière biologique absolue entre absence et présence de maladie.</p>'''+table(['Résultat','Question correcte','Limite'],[
['LDH au-dessus de la référence','Existe-t-il un marqueur de renouvellement ou de lésion tissulaire et un facteur pronostique dans ce contexte ?','Non spécifique d’un lymphome.'],['Ferritine croissante','Le profil s’intègre-t-il à une hyperinflammation et une atteinte d’organes ?','Le seuil HLH de 500 µg/L est peu spécifique chez l’adulte.'],['Albumine basse','Déficit nutritionnel, inflammation, pertes ou fuite capillaire sous traitement ?','Le seuil de 32 g/L avant tagraxofusp est une condition de traitement, pas une norme biologique.'],['CD123 ciblé par tagraxofusp','La néoplasie répond-elle aux critères BPDCN et le patient est-il éligible ?','Une cible exprimée n’est pas un diagnostic ni une garantie de réponse.']])+'''<p>Un calcul d’unité est une mesure de sécurité : 3,2 g/dL d’albumine =32 g/L ; 0,5 g/dL de baisse =5 g/L ; 12 µg/kg de tagraxofusp n’équivaut pas à 12 mg/kg. Les valeurs de la FI conservent le produit, la phase de traitement et la population. Elles ne servent pas de seuils universels pour tous les lymphomes.</p>'''+refs('TSE','ESMO25','ONCASPAR','ELZONRIS','HLH23')+'<button class="pareto-btn ui" data-k="pareto-c86-bio">▲ Loi de Pareto — Biochimie</button></section>'

GEN='''<section class="ilot" id="c86-s-gen-cours"><h2>Génétique : constitutionnel, acquis et clonal ne signifient pas la même chose</h2><p>Une anomalie <b>germinale</b> appartient au patrimoine constitutionnel ; une anomalie <b>somatique</b> apparaît dans une population de cellules. Une <b>clonalité</b> traduit une origine cellulaire commune ou une expansion sélectionnée ; elle ne suffit pas à déclarer une tumeur. Dans C86, ces trois notions se croisent et doivent être distinguées pour éviter une erreur de diagnostic ou de conseil génétique.</p>'''+table(['Situation','Observation documentée','Interprétation prudente'],[
['nTFHL-AI','TET2/DNMT3A précoces dans l’hématopoïèse, puis RHOA/IDH2 dans la population TFH tumorale.','Le sang peut porter une hématopoïèse clonale sans prouver le siège ou le type du lymphome.'],['SPTCL','Variants germinaux HAVCR2 altérant TIM-3, distributions variables selon les cohortes.','Prédisposition et risque inflammatoire ; ni pénétrance complète ni prescription automatique.'],['RCD-II/EATL','Population intraépithéliale aberrante, clonalité et anomalies de voies JAK/STAT.','Le clone est confronté aux symptômes, à l’atrophie et à la recherche de lymphome constitué.'],['pcALCL/LyP','Réarrangements DUSP22–IRF4 dans une partie des cas.','La portée pronostique diffère de celle du lymphome anaplasique systémique ; ne pas transférer un pronostic entre entités.'],['HSTL','Anomalies cytogénétiques telles qu’isochromosome 7q dans les séries décrites.','Un marqueur contribue à un diagnostic intégré, sans remplacer morphologie et phénotype.']])+'''<figure id="c86-gen-causal"><div class="card"><h4>Modèle de transformation TFH</h4><p>Clone hématopoïétique avec anomalies épigénétiques précoces → acquisition d’autres événements dans une population TFH → phénotype tumoral et microenvironnement perturbé.</p></div><figcaption>Modèle causal non anatomique fondé sur l’OMS 2022. Le modèle organise des observations de groupes ; il ne prétend pas reconstituer la chronologie de chaque patient.</figcaption></figure><p>Dans le SPTCL, le résumé de Gayden 2018 décrit deux variants affectant le repliement et l’expression membranaire de TIM-3. Moonla 2023 rapporte une cohorte thaïlandaise et une méta-analyse de données individuelles : sexe masculin et variants HAVCR2 sont associés au HLH ou à un état apparenté. La fréquence des variants dépend du recrutement et de l’ascendance ; le chiffre d’environ 60 % d’une série ne devient pas une fréquence nationale. Les odds ratios élevés avec intervalles larges expriment une association, pas la probabilité qu’un porteur développe un HLH.</p><p>La génétique peut affiner un diagnostic difficile et orienter un essai. Elle ne permet pas de sauter les étapes : une mutation TET2 n’impose pas de l’azacitidine, et une mutation HAVCR2 négative n’exclut pas un HLH. Le résultat, sa qualité et son origine constitutionnelle ou tumorale sont discutés avec l’équipe spécialisée ; une information familiale n’est donnée qu’après interprétation génétique appropriée.</p><div class="trap"><span class="k">Piège</span> Un vocabulaire moderne ne garantit pas une règle plus sûre. Toujours préciser la population, le tissu analysé et le rôle du résultat : diagnostic, pronostic, prédisposition ou cible expérimentale.</div>'''+refs('OMS22','ONKO','GAYDEN','MOONLA','WHO-CUT','ESsCD26','ESMO25')+'<button class="pareto-btn ui" data-k="pareto-c86-gen">▲ Loi de Pareto — Génétique</button></section>'

LINKS={
'semio':('Une ulcération ORL, des cytopénies ou des papules régressives orientent des mécanismes différents, à confronter au contexte.','Choisir le tissu et la profondeur à partir du siège ; distinguer référence de laboratoire et seuil diagnostique.','La menace respiratoire ou le HLH grave peut nécessiter une action pendant le bilan.','Décrire, expliquer, tester puis interpréter ; aucun signe isolé ne résume C86.'),
'anat':('L’infiltration de rate, foie et moelle explique un HSTL sans adénopathie dominante.','Un nodule de l’hypoderme nécessite un prélèvement assez profond ; une tumeur nécrotique demande du tissu exploitable.','Le siège local participe aux volumes de radiothérapie, tandis que l’extension systémique impose une stratégie globale.','Le site guide le prélèvement, sans imposer à lui seul l’entité.'),
'histo':('La même expression de CD30 peut accompagner des évolutions différentes : LyP, pcALCL ou ALCL systémique.','Architecture et panel complètent la cytologie ; une petite carotte peut limiter le sous-typage TFH.','La classification correcte évite une chimiothérapie excessive dans LyP et oriente les traitements ciblés dans leur indication.','Un marqueur et un clone ne constituent pas seuls un diagnostic.'),
'physio':('Une réponse immunitaire dérégulée peut donner fièvre et atteintes d’organes, au-delà de la masse tumorale.','Confronter hémolyse présumée aux réticulocytes, bilirubine, LDH, haptoglobine et test direct à l’antiglobuline.','Le HLH grave peut nécessiter traitement du déclencheur et immunomodulation en parallèle.','Expansion clonale contrôlée et coopération cellulaire sont normales ; leur contexte distingue réaction et maladie.'),
'bio':('LDH, ferritine et albumine varient dans plusieurs mécanismes ; leur dynamique compte autant que la valeur isolée.','Le suivi d’EBV utilise le prélèvement adapté ; une activité enzymatique mesure autre chose qu’une dose prescrite.','La dépendance en asparagine explique une option ENKTL, mais les toxicités pancréatiques, hépatiques et de coagulation imposent la surveillance.','Distinguer signal biologique, seuil de décision et effet clinique ; conserver les unités.'),
'gen':('Une prédisposition HAVCR2 module un risque de groupe sans déterminer l’évolution individuelle.','Préciser tissu, technique et origine germinale ou somatique ; une mutation sanguine peut appartenir à une hématopoïèse clonale.','Une mutation TET2 n’impose pas de l’azacitidine ; un essai et son critère de résultat gardent leur importance.','Constitutionnel, somatique et clonal ne sont pas synonymes.')}
def science_links(name):
 labels=['Science → clinique.','Science → examen.','Science → traitement.','À retenir.']
 return '<div class="key">'+''.join('<p><b>'+label+'</b> '+text+'</p>' for label,text in zip(labels,LINKS[name]))+'</div>'
def causal_svg(label,first,second):
 def lines(parts,y):return ''.join(f'<text x="200" y="{y+i*25}" text-anchor="middle" font-size="18" fill="#173e46">{line}</text>' for i,line in enumerate(parts))
 return f'<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{label}" viewBox="0 0 400 330"><rect x="10" y="10" width="380" height="125" rx="14" fill="#edf5f1" stroke="#38665c"/>'+lines(first,43)+'<path d="M200 140 V180 M188 168 L200 180 L212 168" fill="none" stroke="#8b6a23" stroke-width="4"/><rect x="10" y="190" width="380" height="125" rx="14" fill="#fff8e8" stroke="#8b6a23"/>'+lines(second,225)+'</svg>'
BIO=BIO.replace('<figure id="c86-bio-causal">','<figure id="c86-bio-causal">'+causal_svg('Relation causale non anatomique : capacité de synthèse limitée et déplétion en asparagine', ['Synthèse d’asparagine limitée','+ déplétion extracellulaire','par l’asparaginase'],['Compensation limitée','Vulnérabilité tumorale possible','Réponse à mesurer, non garantie']))
GEN=GEN.replace('<figure id="c86-gen-causal">','<figure id="c86-gen-causal">'+causal_svg('Modèle causal non anatomique de transformation TFH, OMS 2022',['Anomalies épigénétiques','précoces TET2 / DNMT3A','dans un clone hématopoïétique'],['Événements supplémentaires TFH','RHOA / IDH2 dans le modèle','Contexte et tissu à interpréter']))
SEMIO='<section class="ilot" id="c86-s-semio-cours">'+SEMIO+science_links('semio')+'<button class="pareto-btn ui" data-k="pareto-c86-semio">▲ Loi de Pareto — Sémiologie fondamentale</button></section>'
TABS=[('semio','Sémiologie fondamentale et analytique',SEMIO),('anat','Anatomie',ANAT+science_links('anat')),('histo','Histologie',HISTO+science_links('histo')),('physio','Physiologie',PHYSIO+science_links('physio')),('bio','Biochimie',BIO+science_links('bio')),('gen','Génétique',GEN+science_links('gen'))]
def sciences():
 bar='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">'
 for key,title,_ in TABS:
  bar+=f'<button id="c86-tab-{key}" role="tab" aria-selected="{str(key=="semio").lower()}" aria-controls="c86-s-{key}" data-s="c86-s-{key}">{title}</button>'
 bar+='</div><div class="chap-body sci-body">'
 for key,_,body in TABS:
  hidden='' if key=='semio' else ' hidden'
  bar+=f'<div class="sci" id="c86-s-{key}" role="tabpanel" aria-labelledby="c86-tab-{key}"{hidden}>{body}</div>'
 return bar+'</div><div class="pager ui"><button class="prev">← Partie précédente</button><span></span><button class="next">Partie suivante →</button></div></div>'
